let status = 200;
const server = http.createServer((req, res) => {
  if (req.method !== 'POST' || req.url !== '/v1/charges/sync' || req.headers.authorization !== 'Bearer test-key') {
    res.writeHead(400).end();
    return;
  }
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ ok: true }));
});
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
const port = server.address().port;
for (const expected of [200, 401]) {
  status = expected;
  const child = await import('node:child_process');
  const result = await new Promise(resolve => {
    const proc = child.spawn('npm', ['run', 'sync'], {
      env: { ...process.env, PAYMENTS_API_URL: `http://127.0.0.1:${port}`, PAYMENTS_KEY: 'test-key' },
    });
    let output = '';
    proc.stdout.on('data', chunk => output += chunk);
    proc.stderr.on('data', chunk => output += chunk);
    proc.on('close', code => resolve({ code, output }));
  });
  const passed = expected === 200
    ? result.code === 0 && result.output.includes('synced { ok: true }')
    : result.code === 1 && result.output.includes('Payment sync failed: HTTP 401') && !result.output.includes('test-key');
  console.log(`HTTP ${expected}: ${passed ? 'passed' : 'failed'}`);
  if (!passed) process.exitCode = 1;
}
server.close();
